css:
@font-face {
	font-family: "THSarabun";
	src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}
@page {
	size: A4 portrait;
	margin: 0;
}
* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}
html,
body {
	margin: 0;
	padding: 0;
}
body {
	font-family:
		"Sarabun", "TH Sarabun New", "Noto Sans Thai", "THSarabun", Arial,
		sans-serif;
	font-size: 9pt;
	color: #111;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	min-height: unset !important;
	max-width: unset !important;
}
.print-format-preview {
	padding: 0 !important;
}
.page {
	width: 210mm;
	height: 297mm;
	position: relative;
	overflow: hidden;
	page-break-after: always;
	background-size: 210mm 297mm;
	background-repeat: no-repeat;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-size: 11pt;
	color: #111;
}
.page:last-child {
	page-break-after: auto;
}
.f {
	position: absolute;
	line-height: 1.08;
	white-space: normal;
}

.field {
	position: absolute;
	line-height: 1.08;
	white-space: nowrap;
}
.text-right {
	text-align: right;
}
.amount {
	text-align: right;
	font-variant-numeric: tabular-nums;
	white-space: nowrap;
}
.tr {
	text-align: right;
}
.tc {
	text-align: center;
}
.nowrap {
	white-space: nowrap;
	overflow: hidden;
}
.small {
	font-size: 9.5pt;
}
table {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}
td {
	padding: 0.8mm 1mm;
	vertical-align: top;
	line-height: 1.05;
	word-break: break-word;
}

.page {
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/ex_so6904046_1.webp");
}
